unload_new = '''    coreSession = null;\n    coreKey = null;\n    coreLocationKey = null;\n    lastRuntimePromptCacheProbe = null;\n    lastRequestTopologyProbe = null;\n    runtimePromptCache.reset();\n    requestTopology.reset();\n    lastEvidenceMappingProbe = null;'''
